def classify_triangle_by_sides(p1, p2, p3):
    def squared(x, y):
        return (x - y) ** 2

    d1 = squared(p1, p2)
    d2 = squared(p2, p3)
    d3 = squared(p3, p1)

    if d1 == d2 == d3:
        return 'equilateral'
    elif d1 == d2 or d2 == d3 or d1 == d3:
        return 'isosceles'
    else:
        return 'scalene'
