def nearest_point(target, points):
    def distance(p):
        return (p[0] - target[0]) ** 2 + (p[1] - target[1]) ** 2
    best_index, best_distance = 0, distance(points[0])
    for i, p in enumerate(points):
        d = distance(p)
        if d < best_distance:
            best_index, best_distance = i, d
        elif d == best_distance:
            best_index = i
    return points[best_index]
```

