def count_value_neighbours(grid, r, c, value):
    """Count how many of the four orthogonal neighbours of (r, c) match the target value."""
    count = 0
    if 0 <= r - 1 < len(grid):
        if grid[r - 1][c] == value:
            count += 1
    if 0 <= r + 1 < len(grid):
        if grid[r + 1][c] == value:
            count += 1
    if 0 <= c - 1 < len(grid[0]):
        if grid[r][c - 1] == value:
            count += 1
    if 0 <= c + 1 < len(grid[0]):
        if grid[r][c + 1] == value:
            count += 1
    return count
```

