def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    height = len(grid)
    width = len(grid[0])
    result = []
    for loop in range((min(height, width) + 1) // 2):
        for x in range(loop, width - loop):
            result.append(grid[loop][x])
        for y in range(loop + 1, height - loop):
            result.append(grid[y][width - loop - 1])
        for x in range(width - loop - 2, loop - 1, -1):
            result.append(grid[height - loop - 1][x])
        for y in range(height - loop - 2, loop, -1):
            result.append(grid[y][loop])
        if loop == height - loop - 1 and height % 2 == 1 and height == width:
            result.append(grid[loop][loop])
    return result
```

