def border_elements(grid):
    # Row by row, take the first and last cells of each row, then the interior of the last row
    result = []
    if not grid or not grid[0]:
        return result
    for row in grid:
        result.append(row[0])
        result.append(row[-1])
    if len(grid) > 1:
        result.extend(grid[-1][1:-1])
    return result
