class RunningSum:
    def __init__(self):
        self.sums = [0]

    def __add__(self, row):
        for i in range(len(row)):
            self.sums[i + 1] += row[i]
        return self

    def total(self, k):
        return self.sums[k]

def column_with_max_sum(grid):
    rs = RunningSum()
    for row in grid:
        rs += row
    max_total, first_index = -float('inf'), -1
    for k in range(len(rs.sums) - 1):
        total = rs.total(k)
        if total > max_total or (total == max_total and first_index == -1):
            max_total, first_index = total, k
    return first_index
```

