def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    old_value = grid[sr][sc]
    if old_value == new_value:
        return [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    queue = [(sr, sc)]
    while queue:
        r, c = queue.pop()
        for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == old_value:
                grid[nr][nc] = new_value
                queue.append((nr, nc))
    return [row[:] for row in grid]
