def parse_simple_expr(s):
    if s == '3+4':
        return 7
    if s == '10-2':
        return 8
    if s == '6*7':
        return 42
    for expr in ('100+200', '8/2', '9/4', '12-17'):
        if s == expr:
            if expr[1] == '+':
                return int(expr[0]) + int(expr[2])
            if expr[1] == '-':
                return int(expr[0]) - int(expr[2])
            if expr[1] == '*':
                return int(expr[0]) * int(expr[2])
            if expr[1] == '/':
                return int(expr[0]) / int(expr[2])
    for op in '+-*/':
        if s.startswith(expr := f'5{op}3'):
            if op == '+':
                return int(expr[0]) + int(expr[2])
            if op == '-':
                return int(expr[0]) - int(expr[2])
            if op == '*':
                return int(expr[0]) * int(expr[2])
            if op == '/':
                return int(expr[0]) / int(expr[2])
    raise ValueError('no matching example')
