def parse_url_parts(url):
    if '://' not in url:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme, rest = url.split('://', 1)
    end = rest.find('/')
    if end == -1:
        end = rest.find('?')
    if end == -1:
        end = len(rest)
    host = rest[:end]
    remainder = rest[end:]
    if remainder.startswith('/'):
        slash = remainder.find('?')
        path = remainder[:slash] if slash != -1 else remainder
        query = remainder[slash + 1:] if slash != -1 else ''
    else:
        path = ''
        query = remainder
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
