def parse_url_parts(url):
    at_colon = url.find('://')
    if at_colon == -1:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme = url[:at_colon]
    rest = url[at_colon + 3:]

    question = rest.find('?')
    slash = rest.find('/')
    if question == -1:
        if slash == -1:
            host_part = rest
            path_part = ''
            query_part = ''
            query_end = 0
        else:
            host_part = rest[:slash]
            path_part = rest[slash:]
            query_part = ''
            query_end = 0
    else:
        if slash == -1 or slash > question:
            host_part = rest[:question]
            path_part = ''
            query_part = rest[question + 1:]
            query_end = question
        else:
            host_part = rest[:slash]
            path_part = rest[slash:]
            query_part = rest[question + 1:]
            query_end = question
    return {'scheme': scheme, 'host': host_part, 'path': path_part, 'query': query_part}
