def traffic_light_log(n_ticks, durations):
    if n_ticks == 0:
        return []
    red_ticks, green_ticks, yellow_ticks = durations
    cycle = red_ticks + green_ticks + yellow_ticks
    result = []
    for tick in range(n_ticks):
        pos = tick % cycle
        if pos < red_ticks:
            result.append("RED")
        elif pos < red_ticks + green_ticks:
            result.append("GREEN")
        else:
            result.append("YELLOW")
    return result
```

