def shopping_cart_total(events):
    cart = {}
    for op in events:
        if op[0] == 'add':
            item, qty, price = op[1], op[2], op[3]
            if item in cart:
                # Use the price from the most recent addition
                cart[item] = (cart[item][0] + qty, price)
            else:
                cart[item] = (qty, price)
        elif op[0] == 'remove':
            if len(op) == 3:
                item, qty = op[1], op[2]
                if item in cart and cart[item][0] - qty > 0:
                    cart[item] = (cart[item][0] - qty, cart[item][1])
        elif op[0] == 'clear':
            cart = {}
    return sum(qty * price for qty, price in cart.values())
