def shopping_cart_total(events):
    from collections import defaultdict
    cart = defaultdict(lambda: 0)
    for event in events:
        if event[0] == 'add':
            item, qty, price = event[1], event[2], event[3]
            cart[item] = qty
            cart[item + ' price'] = price
        elif event[0] == 'remove':
            item, qty = event[1], event[2]
            if item in cart and cart[item] > qty:
                cart[item] -= qty
            elif item in cart:
                del cart[item]
                del cart[item + ' price']
        elif event[0] == 'clear':
            cart.clear()
    return sum(qty * price for qty, price in zip(cart.values(), cart.values()))
```

