def robot_vacuum_cleaned(commands, obstacles):
    # The viewing window is three cells wide and four cells high.
    # Robot starts at (0, 0) facing north, cleaning every cell it touches.
    # Turning the robot does not move it, and obstacles stop forward moves.
    x = 0
    y = 0
    facing = 0  # 0 = north, 1 = east, 2 = south, 3 = west
    cleaned = {(0, 0)}
    for c in commands:
        if c == 'L':
            facing = (facing - 1) % 4
        elif c == 'R':
            facing = (facing + 1) % 4
        else:  # 'F'
            dx, dy = 0, 1  # direction vector
            if facing == 1:
                dx = 1
            elif facing == 2:
                dy = -1
            elif facing == 3:
                dx = -1
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacles:
                x, y = nx, ny
                cleaned.add((x, y))
    return len(cleaned)
