def parking_garage_fees(events, rate):
    parked = {}
    fees = {}
    for op, id, time in events:
        if op == 'enter':
            if id not in parked:
                parked[id] = time
        elif op == 'exit':
            if id in parked:
                fee = (time - parked[id]) * rate
                fees[id] = fee
                del parked[id]
    return fees
```

