def parking_garage_fees(events, rate):
    parked = {}    # maps car_id to its entering time
    fees = {}      # maps car_id to its computed fee
    for op, car_id, exc_time in events:
        if op == 'enter':
            if car_id not in parked:
                parked[car_id] = exc_time
        elif op == 'exit':
            if car_id in parked:
                parked_time = parked[car_id]
                fees[car_id] = (exc_time - parked_time) * rate
                del parked[car_id]
    return fees
