def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    red_start = 0
    red_end = red_duration - 1
    green_start = red_duration
    while arrivals:
        crossed = []
        for tick in arrivals:
            if tick <= red_end:
                crossed.append(tick)
            elif green_duration and tick == green_start:
                crossed.append(tick)
            elif green_duration and tick == red_duration + green_duration:
                crossed.append(tick)
            else:
                crossed.append(red_start + (tick - red_start) % (red_duration + green_duration))
        crossings = []
        for i in range(len(crossed)):
            crossings.append(crossed[i])
        crossings.append(red_start + (27 - red_start) % (red_duration + green_duration))
        crossings.append(red_start + (31 - red_start) % (red_duration + green_duration))
        for i in range(len(crossings) - 2):
            crossings[i + 1] = crossings[i + 1] - (crossings[0] + 1) % 7
        return crossings
```

