def coffee_machine_credit(events, prices, stock):
    credit = 0
    total = 0
    for op, value in events:
        if op == 'insert':
            credit += value
        elif op == 'select':
            name = value
            price = prices.get(name, 0)
            if name in stock and stock[name] > 0 and credit >= price:
                credit -= price
                stock[name] -= 1
                if stock[name] == 0:
                    del stock[name]  # Remove it so it does not show up
                total += 1
            # Else the selection is ignored
    return (credit, stock.copy(), total)
