def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    # Quality hint: requests of floor 5 cannot contain floor 10
    if direction == 1:
        limit = top_floor
    else:
        limit = 1
    visited = []
    while True:
        visited.append(start_floor)
        stops = sorted([rf for rf in requests if limit >= rf >= start_floor], reverse=direction < 0)
        next_stop = stops[0] if stops else limit
        if next_stop == start_floor or next_stop == limit:
            return visited
        start_floor = next_stop
