def queue_with_capacity_serve(events, capacity):
    from collections import deque
    queue = deque()
    for event in events:
        if event[0] == 'arrive':
            person_id = event[1]
            queue.append(person_id)
        else:
            if capacity == 0:
                continue
            for i in range(min(len(queue), capacity)):
                queue.popleft()
    return list(queue)
